def test_load_kube_config_with_current_context_in_later_file(self):
    # Simulate KUBECONFIG containing multiple files where only a later file
    # defines 'current-context', as is common when splitting cluster/context/user.
    cluster_cfg = {
        'apiVersion': 'v1',
        'kind': 'Config',
        'clusters': [
            {'name': 'default', 'cluster': {'server': TEST_HOST}}
        ]
    }
    context_cfg = {
        'apiVersion': 'v1',
        'kind': 'Config',
        'contexts': [
            {'name': 'simple_token', 'context': {'cluster': 'default', 'user': 'simple_token'}}
        ],
        'current-context': 'simple_token'
    }
    user_cfg = {
        'apiVersion': 'v1',
        'kind': 'Config',
        'users': [
            {'name': 'simple_token', 'user': {'token': TEST_DATA_BASE64}}
        ]
    }
    # Write files and compose KUBECONFIG string with correct separator.
    cluster_file = self._create_temp_file(yaml.safe_dump(cluster_cfg))
    context_file = self._create_temp_file(yaml.safe_dump(context_cfg))
    user_file = self._create_temp_file(yaml.safe_dump(user_cfg))
    kubeconfigs = ENV_KUBECONFIG_PATH_SEPARATOR.join([cluster_file, context_file, user_file])

    # If merging respects kubectl behavior, this should load using current-context
    # from the context file, regardless of file order.
    actual = FakeConfig()
    load_kube_config(config_file=kubeconfigs, client_configuration=actual)
    expected = FakeConfig(host=TEST_HOST,
                          token=BEARER_TOKEN_FORMAT % TEST_DATA_BASE64)
    self.assertEqual(expected, actual)

